import 'package:flutter/material.dart';
import 'rj45_diagram.dart';

class KnowledgeBasePage extends StatefulWidget {
  const KnowledgeBasePage({super.key});
  @override State<KnowledgeBasePage> createState()=>_KnowledgeBasePageState();
}
class _KnowledgeBasePageState extends State<KnowledgeBasePage>{
  String query='';
  final entries=<Map<String,String>>[
    {'group':'Canon G2420','title':'Canon PIXMA G2420 — коды ошибок и обслуживание','body':'1000 — нет бумаги или она неправильно уложена в задний лоток. Загрузите бумагу, выровняйте боковые направляющие по ширине листа, закройте крышку лотка и нажмите OK.\n1070 — загрязнены ролики подачи бумаги. Отмените печать кнопкой Stop и запустите штатную очистку роликов из меню обслуживания принтера или драйвера Canon. Не протирайте ролики агрессивными растворителями.\n1200 — открыт сканирующий блок/крышка. Закройте блок и подождите завершения проверки.\n1300 — замятие бумаги при подаче из заднего лотка. Остановите задание, медленно вытяните лист двумя руками за доступный край; не дёргайте и не используйте острые предметы. Проверьте, не осталось ли обрывков, загрузите бумагу заново и нажмите OK.\n1470/1471 — печатающая головка не установлена или установлена неправильно. Установите головки в соответствующие держатели и до упора нажмите фиксирующую соединительную кнопку.\n1890 — остались транспортировочные/защитные материалы. Выключите принтер кнопкой питания, удалите все оранжевые ленты и защитные элементы, затем включите снова.\nПеред разборкой проверьте гарантию. Не разбирайте узел парковки и не перемещайте каретку с усилием. Официальный список кодов: https://ij.manual.canon/ij/webmanual/ErrorCode/G2020%20series/RU/ERR/err_contents0100.html'},
    {'group':'Canon MF3010','title':'Canon i-SENSYS MF3010 — диагностика и ошибки','body':'ПЕРВИЧНАЯ ПРОВЕРКА: проверьте питание и кабель, дождитесь прогрева, нажмите любую кнопку для выхода из сна. Если мигают индикаторы Paper Jam/Paper — проверьте бумагу в кассете и тракт подачи.\nE + трёхзначный номер: выключите аппарат штатным выключателем, подождите не менее 10 секунд и включите снова. Если код повторяется, запишите его, выключите аппарат, отсоедините питание и сверяйтесь с сервисной документацией/обращайтесь в сервис. Не подставляйте расшифровки от других моделей.\nНЕ ЗАХВАТЫВАЕТ БУМАГУ: проверьте формат и плотность бумаги, правильность установки стопки, боковые направляющие, отсутствие обрывков. При повторении проверьте состояние ролика захвата и площадки отделения.\nБЛЕДНАЯ/СЕРАЯ ПЕЧАТЬ: проверьте тонер-картридж, равномерность распределения тонера допустимым способом, режим экономии тонера и настройки плотности. Не встряхивайте повреждённый или протекающий картридж.\nНЕ СКАНИРУЕТ: проверьте USB-соединение, наличие MF Drivers и MF Toolbox, выберите MF3010 как источник сканирования. Если ПК зависает при сканировании высокого разрешения, закройте лишние программы и проверьте свободное место на диске.\nОфициальное руководство: https://oip.manual.canon/USRM1-9803-zz-SSM-enUS/contents/devu-trb-trb.html'},
    {'group':'Canon MF463dw','title':'Canon i-SENSYS MF463dw — ошибки и диагностика','body':'У MF463dw ошибки передачи/печати отображаются в отчёте или журнале заданий как трёхзначный номер с символом #. Сначала откройте Монитор состояния/журнал заданий, перепишите полный код и определите, при какой операции он появился: печать, сканирование в папку, e-mail, USB или факс.\n#806 — адресат отказал в доступе. При сканировании в общую папку/FTP проверьте имя пользователя и пароль: они должны совпадать с учётными данными на целевом ПК/сервере. Проверьте права на общую папку (изменение/запись), имя сервера/IP и путь. При отправке e-mail проверьте адрес получателя и запись адресной книги.\n«Несоответствие формата бумаги и параметров» — сравните формат/тип бумаги в драйвере задания с настройками кассеты на аппарате; подтвердите нужный источник бумаги или исправьте параметры задания.\n«Память заполнена» — проверьте очередь и незавершённые задания, отмените ненужные задания, повторите операцию меньшим объёмом/разрешением.\n«USB-память ограничена» — проверьте настройки ограничений использования USB-носителей и политику администратора.\nПри сетевой печати: распечатайте отчёт конфигурации, проверьте IP, маску, шлюз, DNS, доступность веб-интерфейса Remote UI и порт драйвера. Не сбрасывайте сетевые настройки без записи текущих параметров.\nОфициальная справка Canon по #806: https://oip.manual.canon/FAQ01-0498-zz-SSM_n4-ruRU/contents/cmcont-msg_error-error806.html. Полное руководство: https://gdlp01.c-wss.com/gds/8/0300047258/01/MF465dw_UsersGuide_EN.pdf'},
    {'group':'Canon MF411dw','title':'Canon i-SENSYS MF411dw — обслуживание и диагностика','body':'СНАЧАЛА: откройте Монитор состояния → Информация об ошибках/уведомлениях. Запишите точный текст сообщения и трёхзначный код. В руководстве MF411dw ошибки описаны отдельно от других поколений Canon MF.\nЗАМЯТИЕ: посмотрите указание на дисплее, откройте только обозначенные крышки, извлекайте лист медленно по направлению движения бумаги. Проверьте тракт, дуплекс и автоподатчик (если замятие оригинала). Не оставляйте обрывки бумаги.\nСЕТЕВАЯ ПЕЧАТЬ: проверьте IP-адрес аппарата в отчёте сети, совпадение подсети ПК и МФУ, шлюз и состояние порта в свойствах принтера Windows. Для проверки откройте IP аппарата в браузере.\nСКАНИРОВАНИЕ В ПАПКУ: проверьте доступность ПК по сети, SMB-общую папку, права записи, имя пользователя/пароль и правильность пути.\nПЛОХОЕ КАЧЕСТВО: проверьте тонер-картридж, бумагу, настройки типа бумаги и режим экономии тонера; распечатайте внутренний отчёт/страницу состояния.\nОфициальное руководство (семейство MF411dw): https://oip.manual.canon/USRMA-0836-zz-SS-ruRU/contents/SS419_troubleshooting_264troubleshooting.html'},
    {'group':'Pantum M7100','title':'Pantum M7100 — ошибки, замятия и обслуживание','body':'КАРТРИДЖ НЕ ОБНАРУЖЕН: остановите печать, откройте переднюю крышку, извлеките картридж за ручку, проверьте правильность модели, отсутствие упаковочных элементов и корректную установку по направляющим. Не касайтесь фотобарабана и контактов руками.\nЗАМЯТИЕ В СРЕДНЕЙ ЧАСТИ: выдвиньте лоток и аккуратно удалите лист; если бумага осталась внутри, откройте переднюю крышку, извлеките картридж и осторожно достаньте бумагу.\nЗАМЯТИЕ В ПЕЧКЕ: печка может быть горячей. Выключите аппарат, дайте узлу остыть, откройте заднюю крышку и используйте предусмотренные ручки доступа. Не касайтесь нагревательного вала и не применяйте металлические предметы.\nЗАМЯТИЕ В ДУПЛЕКСЕ: извлеките модуль двусторонней печати сзади и удалите лист; проверьте нижнюю часть тракта.\nЗАМЯТИЕ В АПД: откройте верхнюю крышку автоподатчика и извлеките оригинал без рывков.\nПЛОТНАЯ/БЛЕДНАЯ ПЕЧАТЬ: проверьте режим экономии, тип бумаги, тонер и совместимость картриджа.\nОфициальная инструкция Pantum по замятию M7100: https://support.pantum.com/index/productcenter/faqview/id/248.html'},
    {'group':'Pantum M6500','title':'Pantum M6500 — частые неисправности','body':'КАРТРИДЖ НЕ ОБНАРУЖЕН: выключите аппарат, извлеките картридж, проверьте маркировку и отсутствие упаковки, установите до упора. Осмотрите контактные площадки на загрязнение или повреждение.\nЗАМЯТИЕ БУМАГИ: выньте кассету и проверьте листы; затем проверьте доступный тракт, область картриджа и заднюю крышку. Тяните лист медленно, не оставляйте обрывков. Если бумага застряла в горячем узле закрепления, дождитесь остывания.\nПЕЧАТЬ БЛЕДНАЯ: проверьте тонер, картридж, настройки плотности и режим экономии.\nПРИНТЕР НЕ ВИДЕН ПО USB: проверьте кабель напрямую без USB-хаба, другой порт, очередь и драйвер Pantum.\nПРИНТЕР НЕ ВИДЕН ПО СЕТИ: проверьте IP-адрес на панели/отчёте, кабель и принадлежность ПК к нужной подсети.\nТочные сообщения зависят от модификации M6500/M6500W/M6500N; перепишите текст с дисплея и сверяйте с руководством именно своей версии.'},
    {'group':'RJ45','title':'Распиновка RJ45 — T568B','body':'Смотреть на контакты штекера, золотые контакты вверх, защёлка с обратной стороны, кабель направлен от себя. Слева направо: 1 бело-оранжевый; 2 оранжевый; 3 бело-зелёный; 4 синий; 5 бело-синий; 6 зелёный; 7 бело-коричневый; 8 коричневый. Одинаковая схема на обоих концах — прямой кабель.'},
    {'group':'RJ45','title':'Распиновка RJ45 — T568A','body':'Смотреть на контакты штекера, золотые контакты вверх, защёлка с обратной стороны, кабель направлен от себя. Слева направо: 1 бело-зелёный; 2 зелёный; 3 бело-оранжевый; 4 синий; 5 бело-синий; 6 оранжевый; 7 бело-коричневый; 8 коричневый. T568A на одном конце и T568B на другом образуют crossover; для современных устройств обычно используется прямой кабель.'},
    {'group':'Windows 10/11','title':'Частые ошибки Windows','body':'Нет сети: проверьте кабель/Wi‑Fi, ipconfig /all, шлюз, DNS; затем ipconfig /flushdns.\nНе печатает: проверьте принтер по умолчанию, очередь, службу «Диспетчер печати» (Spooler), драйвер и порт.\nНет звука: проверьте устройство вывода и микшер громкости.\nМало места: очистите временные файлы и проверьте диск.\nСиний экран: запишите STOP-код, проверьте журнал событий, драйверы и последние изменения. Не удаляйте системные файлы наугад.'},
    {'group':'Office','title':'Частые ошибки Microsoft Office','body':'Не открывается документ: попробуйте Файл → Открыть → Обзор → стрелка рядом с «Открыть» → «Открыть и восстановить».\nOffice просит активацию: проверьте учётную запись/лицензию и дату-время.\nНадстройки мешают запуску: запустите приложение в безопасном режиме (например, Win+R → excel /safe).\nОшибки установки/обновления: перезагрузите ПК, проверьте свободное место и выполните восстановление Office через «Приложения и возможности».'},
    {'group':'Windows 10/11','title':'Полезные сочетания клавиш','body':'Win+E — Проводник. Win+R — Выполнить. Win+I — Параметры. Win+D — рабочий стол. Win+L — блокировка. Win+Tab — представление задач. Alt+Tab — переключение окон. Ctrl+Shift+Esc — Диспетчер задач. Win+Shift+S — фрагмент экрана. Win+P — режим вывода на экран. Win+X — системное меню. Ctrl+C / Ctrl+V / Ctrl+X — копировать / вставить / вырезать. Ctrl+Z — отмена. F2 — переименовать. Shift+Delete — удалить без корзины.'},
    {'group':'Windows 10/11','title':'Коды ошибок Windows и обновлений','body':'0x80070005 — отказано в доступе. Проверьте права пользователя, запуск от имени администратора, доступ к папкам и защитное ПО.\n0x80070002 — не найден указанный файл. Проверьте путь, наличие файла и целостность системных компонентов.\n0x80070422 — требуемая служба отключена. Откройте services.msc и проверьте службу, указанную в сообщении ошибки; не включайте неизвестные службы вслепую.\n0x800F081F — не найдены исходные файлы для восстановления компонентов Windows. Проверьте подключение, источник установки и соответствие версии/сборки Windows.\n0x80070057 — неверный параметр. Запишите, какая операция вызывает ошибку, проверьте параметры приложения и диск.\nПеред изменением реестра и системных компонентов создайте точку восстановления. Для точной диагностики важны полный код, текст сообщения и действие, при котором ошибка возникает.'},
    {'group':'Windows 10/11','title':'Восстановление системных файлов Windows','body':'Откройте Терминал или CMD от имени администратора. Сначала выполните: DISM /Online /Cleanup-Image /RestoreHealth. Дождитесь завершения, затем: sfc /scannow.\nDISM восстанавливает хранилище компонентов, SFC проверяет и восстанавливает защищённые системные файлы. Не закрывайте окно во время проверки. После завершения перезагрузите ПК и проверьте, повторяется ли проблема.\nЕсли DISM сообщает, что исходные файлы не найдены, может понадобиться ISO той же редакции, языка и сборки Windows.'},
    {'group':'Windows 10/11','title':'Диагностика сети — команды','body':'ipconfig /all — адреса, шлюз, DNS, DHCP и MAC.\nipconfig /release и ipconfig /renew — обновить DHCP-адрес (только для DHCP, не для статического адреса).\nipconfig /flushdns — очистить кэш DNS.\nping 127.0.0.1 — проверить TCP/IP стек локально; ping адрес_шлюза — проверить связь с маршрутизатором; ping 8.8.8.8 — проверить выход по IP; nslookup имя_сайта — проверить DNS.\ntracert адрес — посмотреть маршрут. route print — таблица маршрутизации. getmac /v — MAC-адреса интерфейсов.\nPowerShell: Test-NetConnection 192.168.1.10 -Port 445 — проверить доступность TCP-порта SMB.\nНе делайте netsh winsock reset и сброс IP первым шагом: это может затронуть VPN, статические настройки и сетевые адаптеры. Сначала сохраните текущие параметры.'},
    {'group':'Windows 10/11','title':'Очередь печати и служба Диспетчер печати','body':'1. Проверьте, выбран ли нужный принтер и не включён ли режим «Работать автономно». 2. Откройте очередь и отмените зависшие задания. 3. Нажмите Win+R, введите services.msc и найдите «Диспетчер печати» (Print Spooler). Служба должна быть запущена; при зависании выполните перезапуск.\nЕсли очередь не очищается: остановите службу Print Spooler, удалите файлы заданий из C:\\Windows\\System32\\spool\\PRINTERS, затем запустите службу снова. Делайте это только при закрытых окнах печати и с правами администратора.\nЕсли проблема повторяется, проверьте драйвер, порт (USB/WSD/TCP-IP), IP-адрес принтера и журнал событий. Не удаляйте драйверы, пока не убедились, что есть установочный пакет нужной модели.'},
    {'group':'Сканирование в папку SMB','title':'Canon/Pantum — сканирование в сетевую папку Windows','body':'На ПК создайте отдельную папку, например Scan. В свойствах папки откройте общий доступ и выдайте нужному пользователю права на изменение/запись. Запишите имя ПК или IP, имя общей папки, имя пользователя и пароль.\nНа МФУ укажите адрес ПК, путь к общей папке, протокол SMB и те же учётные данные. Для диагностики проверьте с другого ПК открытие \\\\ИМЯ-ПК\\Scan, доступность TCP 445 и правильность времени/сетевого профиля.\nНе отключайте брандмауэр полностью и не включайте SMB1 без необходимости. Предпочитайте SMB2/SMB3 и отдельную учётную запись с ограниченными правами. При #806 на MF463dw проверьте пароль, имя пользователя и права на запись.'},
  ];
  @override Widget build(BuildContext context){
    final list=entries.where((e)=>[e['group']!,e['title']!,e['body']!].join(' ').toLowerCase().contains(query.toLowerCase())).toList();
    return Scaffold(body:ListView(padding:const EdgeInsets.all(16),children:[
      TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Поиск по моделям, кодам и темам',border:OutlineInputBorder()),onChanged:(v)=>setState(()=>query=v)),
      const SizedBox(height:12),
      const Card(child:Padding(padding:EdgeInsets.all(12),child:Text('Справочник можно расширять. Для точной расшифровки всегда сверяйте полный код и текст сообщения с руководством именно вашей модификации устройства.'))),
      const SizedBox(height: 10),
      const RJ45WiringCard(),
      ...list.map((e)=>Card(elevation:0,child:ExpansionTile(
        title:Text(e['title']!,style:const TextStyle(fontWeight:FontWeight.w600)),
        subtitle:Text(e['group']!),
        children:[Padding(padding:const EdgeInsets.fromLTRB(16,0,16,16),child:SelectableText(e['body']!))],
      ))),
      if(list.isEmpty) const Padding(padding:EdgeInsets.all(24),child:Text('Ничего не найдено.',textAlign:TextAlign.center)),
    ]));
  }
}
